from accountability.authorization import intersection_pattern, pattern_matches
from collections import Counter

def ref_intersection(first, second):
    """Independent reference: strict layout model with brute-force middle check."""
    def split(p):
        parts = p.split("*")
        return parts[0], tuple(x for x in parts[1:-1] if x), parts[-1]
    if "*" not in first:
        if "*" not in second:
            return first if first == second else None
        return first if pattern_matches(second, first) else None
    if "*" not in second:
        return second if pattern_matches(first, second) else None
    fp, fm, fs = split(first)
    sp, sm, ss = split(second)
    if not (fp.startswith(sp) or sp.startswith(fp)):
        return None
    if not (fs.endswith(ss) or ss.endswith(fs)):
        return None
    prefix = fp if len(fp) >= len(sp) else sp
    suffix = fs if len(fs) >= len(ss) else ss
    # brute-force middle compatibility + merge
    cf, cs = Counter(fm), Counter(sm)
    target = {f: max(cf.get(f,0), cs.get(f,0)) for f in set(cf)|set(cs)}
    pool = []
    for f in sorted(target):
        pool += [f]*target[f]
    def is_subseq(run, S):
        it = iter(S)
        return all(any(x == y for y in it) for x in run)
    best = None
    for perm in set(itertools.permutations(pool)):
        if is_subseq(fm, perm) and is_subseq(sm, perm):
            if best is None or perm < best:
                best = perm
    if best is None:
        return None
    return "*".join([prefix, *best, suffix])

